--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,26 @@
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+import { importSales } from "../domain/sales.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+/** Parses a sales CSV and imports it as one transaction. */
+export function importSalesCsv(store, text) {
+  const lines = text.split(/\r?\n/);
+  const parsed = [];
+  for (let i = 0; i < lines.length; i++) {
+    if (!lines[i].trim()) continue;
+    if (!/^(?:"(?:[^"\r\n]|"")*"|[^",\r\n]*)(?:,(?:"(?:[^"\r\n]|"")*"|[^",\r\n]*))*$/.test(lines[i]))
+      throw new AppError("sales_row", { row: i + 1, reason: "malformed CSV" });
+    parsed.push({ fields: parseCsv(lines[i])[0].map((v) => v.trim()), row: i + 1 });
+  }
+  const header = parsed.shift()?.fields ?? [];
+  if (header.length !== HEADER.length || HEADER.some((key) => !header.includes(key)))
+    throw new AppError("sales_row", { row: 1, reason: "expected columns ticket,soldAt,dishId,qty" });
+  const rows = parsed.map(({ fields, row }) => {
+    if (fields.length !== header.length) throw new AppError("sales_row", { row, reason: "wrong number of fields" });
+    const values = Object.fromEntries(header.map((key, i) => [key, fields[i]]));
+    return { ...values, dishId: Number(values.dishId), qty: Number(values.qty), row };
+  });
+  return importSales(store, rows);
+}
